from flask import Flask
app = Flask(__name__)
@app.route('/', defaults={'path': ''})
@app.route('/<path:path>')
def home(path):
    return """<!DOCTYPE html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Numora USA</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:sans-serif}body{background:#f6f7fb}.top{background:#fff;padding:14px;border-bottom:1px solid #eee;display:flex;gap:10px}.logo{font-weight:900}.logo span{color:#2563eb}.q{flex:1;background:#f1f5f9;padding:8px;border-radius:8px;display:flex;gap:6px}.q input{border:0;background:transparent;outline:none;width:100%}.hero{margin:12px;background:linear-gradient(135deg,#111,#2563eb);color:#fff;padding:20px;border-radius:16px}.card{background:#fff;margin:10px;padding:14px;border-radius:12px;border:1px solid #eee;display:flex;gap:12px}.btn{background:#111;color:#fff;padding:10px;border-radius:8px;border:0;width:100%;margin-top:8px}</style></head><body><div class=top><div class=logo>num<span>ora</span></div><div class=q>🔍<input id=q placeholder='Search...' oninput='render()'></div></div><div class=hero><h2>USA Remote Jobs</h2><p>Work from Kenya</p></div><div id=grid></div><script>jobs=[{t:'Customer Support USA',c:'Amazon',s:'$18/hr'},{t:'Data Entry',c:'US Tech',s:'$22/hr'},{t:'Virtual Assistant',c:'HireUSA',s:'$25/hr'}];function render(){let q=document.getElementById('q').value.toLowerCase();let h='';jobs.filter(j=>!q||j.t.toLowerCase().includes(q)).forEach(j=>{h+=`<div class=card><div style='flex:1'><b>${j.t}</b><br><small>${j.c} • ${j.s}</small><br><button class=btn onclick="alert('Applied!')">Apply</button></div></div>`});document.getElementById('grid').innerHTML=h}render()</script></body></html>"""
